import{_ as i,c as a,o as l,a3 as n}from"./chunks/framework.BurWKwwG.js";const u=JSON.parse('{"title":"Update & TODO List","description":"","frontmatter":{},"headers":[],"relativePath":"6_update.md","filePath":"6_update.md"}'),r={name:"6_update.md"};function t(o,e,s,d,h,c){return l(),a("div",null,e[0]||(e[0]=[n('<h1 id="update-todo-list" tabindex="-1">Update &amp; TODO List <a class="header-anchor" href="#update-todo-list" aria-label="Permalink to “Update &amp; TODO List”">​</a></h1><h2 id="version-history" tabindex="-1">Version History <a class="header-anchor" href="#version-history" aria-label="Permalink to “Version History”">​</a></h2><h3 id="version-3-1-0-latest" tabindex="-1">Version 3.1.0 (Latest) <a class="header-anchor" href="#version-3-1-0-latest" aria-label="Permalink to “Version 3.1.0 (Latest)”">​</a></h3><ul><li><strong>Release Date</strong>: 2026/09/20</li><li><strong>Network Analysis major upgrade</strong> (<code>/network</code>): <ul><li>ID mapping report before building; unmatched names flagged</li><li>Full STRING species support (12,000+); file-upload input fixed</li><li><strong>Network Expansion</strong>: add top-scoring first-shell partners (0-20 per protein); human networks use a bundled local STRING index (instant, offline-capable)</li><li>Visualization: Morandi color system with preset and fully custom palettes; evidence-channel edge coloring with legend; node size/color mapped to centrality metrics; live confidence edge filter; shortest-path highlighting; six layouts (adds cose-bilkent); gentle graph fade-in</li><li>Node dialog: functional annotations (STRING) and deep links into CBD biomarker entries; edge dialog: dominant evidence channel and supporting publications (Europe PMC)</li><li>Analysis tabs: Topology (with path finder), Enrichment (with FDR and gene counts), <strong>Modules</strong> (Louvain detection, isolation, module-level enrichment), <strong>Proximity Test</strong> (cohesion z-score / empirical p-value via degree-matched randomization on the local human index), <strong>Compare</strong> (two-set union network with membership coloring and Jaccard index)</li><li>Downloads: PNG/SVG/GraphML plus a full analysis bundle (edges TSV, enrichment TSV, module assignments, GraphML, JSON snapshot) generated from the exact on-screen state</li><li>Backend: new STRING proxy routes (resolve / expand / abstracts / annotations / species / proximity) and a dedicated rate limit; relaxed global API limit for STRING routes</li></ul></li></ul><h3 id="version-3-0-0" tabindex="-1">Version 3.0.0 <a class="header-anchor" href="#version-3-0-0" aria-label="Permalink to “Version 3.0.0”">​</a></h3><ul><li><strong>Release Date</strong>: 2025/12/12</li><li><strong>Major Changes</strong>: <ul><li>Complete platform redesign with Vue 3 + Vite</li><li>Biomarker browsing and advanced multi-condition search</li><li>Gene Expression Atlas with interactive UMAP visualization (10,000 cells default)</li><li>Protein-protein interaction network explorer (Cytoscape.js)</li><li>Gene autocomplete with 300ms debounce across search fields</li><li>Bilingual help documentation (English/Chinese, VitePress)</li><li>Backend: Express 5 + MySQL2, 12+ database tables, ~36.4M rows</li></ul></li></ul><h3 id="version-2-0-0" tabindex="-1">Version 2.0.0 <a class="header-anchor" href="#version-2-0-0" aria-label="Permalink to “Version 2.0.0”">​</a></h3><ul><li>Migration to Vue 3 framework</li><li>Introduction of single-cell analysis module</li><li>Database schema optimization</li></ul><h3 id="version-1-0-0-2018" tabindex="-1">Version 1.0.0 (2018) <a class="header-anchor" href="#version-1-0-0-2018" aria-label="Permalink to “Version 1.0.0 (2018)”">​</a></h3><ul><li>Basic biomarker database</li><li>Simple search functionality</li></ul><h2 id="known-issues" tabindex="-1">Known Issues <a class="header-anchor" href="#known-issues" aria-label="Permalink to “Known Issues”">​</a></h2><h3 id="high-priority" tabindex="-1">High Priority <a class="header-anchor" href="#high-priority" aria-label="Permalink to “High Priority”">​</a></h3><ul><li><strong>Large Dataset Loading</strong>: Performance may degrade when loading datasets with &gt;100,000 cells <ul><li><strong>Workaround</strong>: UMAP defaults to 10,000 cells; use filters where available</li></ul></li></ul><h3 id="medium-priority" tabindex="-1">Medium Priority <a class="header-anchor" href="#medium-priority" aria-label="Permalink to “Medium Priority”">​</a></h3><ul><li><strong>Browser Compatibility</strong>: Minor display issues in Safari <ul><li><strong>Workaround</strong>: Use Chrome or Firefox for optimal experience</li></ul></li></ul><h2 id="roadmap" tabindex="-1">Roadmap <a class="header-anchor" href="#roadmap" aria-label="Permalink to “Roadmap”">​</a></h2><h3 id="planned" tabindex="-1">Planned <a class="header-anchor" href="#planned" aria-label="Permalink to “Planned”">​</a></h3><ul><li>Single-cell analysis suite (DEGs, KEGG pathway, ridge ranking, trajectory, CellChat, network sensitivity, predictive ROC)</li><li>Clinical analysis pages (Kaplan-Meier survival, immune infiltration)</li><li>API documentation for programmatic access</li><li>Expanded dataset coverage</li><li>Performance optimizations for large-scale visualizations</li><li>Mobile-responsive improvements</li></ul>',18)]))}const m=i(r,[["render",t]]);export{u as __pageData,m as default};
